package com.letstudy.backend.controller;
import com.letstudy.backend.model.*; import com.letstudy.backend.repository.*; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/topics") public class TopicController {private final TopicRepository repo;private final SubjectRepository subjects;public TopicController(TopicRepository repo,SubjectRepository subjects){this.repo=repo;this.subjects=subjects;}@GetMapping public List<Topic> all(){return repo.findAll();}@GetMapping("/subject/{subjectId}") public List<Topic> bySubject(@PathVariable Long subjectId){return repo.findBySubject(subjects.findById(subjectId).orElseThrow());}@GetMapping("/{id}") public Topic one(@PathVariable Long id){return repo.findById(id).orElseThrow();}@PostMapping("/subject/{subjectId}") public Topic add(@PathVariable Long subjectId,@RequestBody Topic input){Topic t=new Topic();t.setName(input.getName());t.setFormLevel(input.getFormLevel());t.setSubject(subjects.findById(subjectId).orElseThrow());return repo.save(t);}@PutMapping("/{id}") public Topic update(@PathVariable Long id,@RequestBody Topic input){Topic t=repo.findById(id).orElseThrow();t.setName(input.getName());t.setFormLevel(input.getFormLevel());if(input.getSubject()!=null&&input.getSubject().getId()!=null)t.setSubject(subjects.findById(input.getSubject().getId()).orElseThrow());return repo.save(t);}@DeleteMapping("/{id}") public void delete(@PathVariable Long id){repo.deleteById(id);}}
